+import {useEffect,useRef,useState} from 'react';
+import {X} from 'lucide-react';
+import {Dialog} from './Dialog';
+import {Button,IconButton,Slider} from './controls';
+import type {EditorApplication} from '../editor';
+
+export function FrequencySeparationDialog({editor,layerId,onClose,onBusyChange,onCreated}:{editor:EditorApplication;layerId:string;onClose():void;onBusyChange(value:boolean):void;onCreated():void}){
+ const [sigma,setSigma]=useState(4),[running,setRunning]=useState(false),[error,setError]=useState('');
+ const pending=useRef<AbortController|null>(null),sourceDocument=useRef(editor.document);
+ useEffect(()=>()=>pending.current?.abort(),[]);
+ const close=()=>{pending.current?.abort();onClose();};
+ const run=async()=>{const abort=new AbortController();pending.current=abort;setRunning(true);setError('');onBusyChange(true);
+  try{if(editor.document!==sourceDocument.current)throw new Error("The selected document changed. Close this dialog and retry.");await editor.separateFrequencies(layerId,{sigma},{signal:abort.signal});if(!abort.signal.aborted){onCreated();onClose();}}
+  catch(cause){if(!abort.signal.aborted)setError(cause instanceof Error?cause.message:String(cause));}
+  finally{onBusyChange(false);if(!abort.signal.aborted)setRunning(false);}
+ };
+ return <Dialog titleId="frequency-separation-title" onClose={close} localEscape>
+  <div className="dialog-heading"><h2 id="frequency-separation-title">Frequency separation</h2><IconButton label="Close frequency separation" onClick={close}><X size={18}/></IconButton></div>
+  <p>Separate color and tone from fine detail. The original stays available as a hidden layer; each band gets its own retouch layer and editable filter.</p>
+  <Slider label="Separation radius" value={sigma} min={0} max={4096/3} step={0.1} suffix="px" scale="quadratic" disabled={running} onPreview={setSigma} onCommit={setSigma}/>
+  <p className="section-description">The radius uses original image pixels. Source transparency is retained as an editable group mask. A protected precision layer keeps the initial 8-bit reconstruction exact. Keep it above both retouch bands.</p>
+  {running&&<p role="status">Preparing native source and editable frequency bands…</p>}
+  {error&&<p role="alert">{error}</p>}
+  <div className="dialog-actions"><Button onClick={close}>{running?'Cancel separation':'Cancel'}</Button><Button variant="primary" disabled={running} onClick={()=>void run()}>Create frequency layers</Button></div>
+ </Dialog>;
+}

